  "batch4.relations.principle_9.title": "All writes are idempotent",
  "batch4.relations.principle_9.desc": "Every request includes a UUID and idempotency key so it executes exactly once without duplication on resubmission.",
  "batch4.relations.principle_10.title": "The system supports multiple projects",
  "batch4.relations.principle_10.desc": "Complete project-level isolation of data, records and documents, supporting carriers operating across multiple projects.",
  "batch4.relations.principle_11.title": "The system is offline-first",
  "batch4.relations.principle_11.desc": "The interface works offline using IndexedDB and synchronizes operations automatically when connectivity returns.",
  "batch4.relations.principle_12.title": "All sensitive changes create an audit log",
  "batch4.relations.principle_12.desc": "An immutable Append-Only audit log records the actor, time and differences for every sensitive change.",
